function clienteCtrl(n,t,i,r,u){"use strict";let f=JSON.parse(localStorage.getItem("accion"));f===null?location.href="/Home/Index":n.accion=f[0];const e="/Cliente/";n.maxSize=5;n.totalRecords=0;n.pageIndex=1;n.pageSize=1e3;n.recordsQuantity=[10,25,50,100,500,1e3];n.dataSearch={pageIndex:1,pageSize:100};n.onKeyupSearchCliente=()=>{n.getClientes()};n.resetList=()=>{n.dataSearch.bySearch=null,n.getClientes()};n.getClientes=()=>{try{showLoader();n.dataSearch.bySearch||null;t.getData("get",e+"Get?json="+JSON.stringify(n.dataSearch)).then(t=>{t.id==0&&(hideLoader(),u.toastr("warning",t.message,t.titleSms)),n.clientes=JSON.parse(t.payload)||[],n.totalRecords=n.clientes.length>0?n.clientes[0].totalRecords:0,hideLoader()})}catch(i){console.log(i);hideLoader()}};n.getClientes();n.openModal=async t=>{const{MODAL_CTRL:u,MODAL_CSHTML:f}=r.cliente,{ModalClienteCtrl:e}=await import("./../../modal/"+u),o=i.openModalCustom({controller:e,template:"Cliente/"+f,size:"xl",params:t});o.result.then(t=>{typeof t=="object"&&n.getClientes()})};n.eliminarCliente=async i=>{let{isConfirmed:r}=await Swal.fire({html:`<small>Esta Ud. seguro de Inactivar al Cliente <b>${i.nombreFiscal}</b></small>?`,icon:"warning",showConfirmButton:!0,confirmButtonText:"Sí, Inactivar!",showCancelButton:!0,cancelButtonText:"No, cancelar!",allowOutsideClick:!1});if(r){let r=await t.getData("delete",e+"Delete?idCliente="+i.idCliente);r.id==="0"&&u.toastr("warning",r.message,r.titleSms);r.id==="1"&&(u.toastr("success",r.message,r.titleSms),n.getClientes())}}}app.controller("clienteCtrl",clienteCtrl);clienteCtrl.$inject=["$scope","mainService","modalService","nombreModal","toastService",];